import {describe,it,expect,vi} from 'vitest'
import {resetCodingPlan} from '../../src/zcode-plan-reset.js'
const data={available_five_hour_resets:[{expire_at:1900000000000}],available_week_resets:[],latest_five_hour_reset_history:{used_at:1800000000000},latest_week_reset_history:null,has_unread_history:true}
const credential={zcode_jwt:'fixture-zcode',device_mid:'test',bigmodel_access_token:'fixture-business'}
const scope={credential,assertCurrent:vi.fn()}
const response=(d:unknown,code=0,status=200)=>new Response(JSON.stringify({code,data:d}),{status})
describe('ZCode真实编程套餐额度重置',()=>{
 it('个人状态使用双登录态与PERSONAL，不带API Key；公开状态没有凭据',async()=>{const f=vi.fn(async(...args:any[])=>response(data));const r=await resetCodingPlan(scope,'status',{},f as any);expect(r).toEqual({availableFiveHourResets:[{expireAt:1900000000000}],availableWeekResets:[],latestFiveHourResetHistory:{usedAt:1800000000000},latestWeekResetHistory:null,hasUnreadHistory:true});expect(JSON.stringify(r)).not.toContain('fixture-');const [url,init]=f.mock.calls[0];expect(url).toBe('https://zcode.z.ai/api/v1/coding-plan/reset/status');expect(init.method).toBe('GET');expect(init.headers).toEqual({Authorization:'Bearer fixture-zcode','X-Bigmodel-Authorization':'fixture-business','Bigmodel-Target-Type':'PERSONAL'});})
 it('团队scope和Z.ai平台精确隔离，不能用国内token覆盖',async()=>{const f=vi.fn(async(...args:any[])=>response(data));await resetCodingPlan({...scope,credential:{...credential,zai_access_token:'fixture-zai'},organizationId:'org',projectId:'project'},'status',{},f as any);const init=f.mock.calls[0][1];expect(init.headers['X-Bigmodel-Authorization']).toBe('fixture-zai');expect(init.headers['Bigmodel-Target-Type']).toBe('TEAM');expect(init.headers['Bigmodel-Organization']).toBe('org');expect(init.headers['Bigmodel-Project']).toBe('project');})
 it('核销必须由用户确认；请求携带原幂等键及准确周期，不自动重试',async()=>{const f=vi.fn(async(...args:any[])=>response({used:true}));await expect(resetCodingPlan(scope,'use',{idempotencyKey:'same-key',resetType:'WEEK'},f as any)).rejects.toThrow('确认');expect(f).not.toHaveBeenCalled();await resetCodingPlan(scope,'use',{idempotencyKey:'same-key',resetType:'WEEK',confirmed:true},f as any);expect(JSON.parse(f.mock.calls[0][1].body)).toEqual({idempotency_key:'same-key',reset_type:'WEEK'});expect(f).toHaveBeenCalledTimes(1);})
 it('资格拒绝保留next_try_at，不能马上循环请求；裸429不吞错',async()=>{expect(await resetCodingPlan(scope,'opportunity',{idempotencyKey:'opportunity'},(async()=>response({next_try_at:1900000000000},3301,429)) as any)).toEqual({granted:false,nextTryAt:1900000000000});await expect(resetCodingPlan(scope,'opportunity',{idempotencyKey:'opportunity'},(async()=>new Response('<html>private detail</html>',{status:429})) as any)).rejects.toThrow('HTTP 429');})
 it('不泄露HTML和服务端随意文案；业务失败不能包装成成功',async()=>{const f=vi.fn(async(...args:any[])=>response({used:true},3101,401));await expect(resetCodingPlan(scope,'use',{idempotencyKey:'key',resetType:'FIVE_HOUR',confirmed:true},f as any)).rejects.toThrow('业务码 3101');expect(f).toHaveBeenCalledTimes(1);await expect(resetCodingPlan(scope,'status',{},(async()=>new Response('<html>credential-secret</html>')) as any)).rejects.toThrow('格式无效');})
 it('无凭据、过期账号scope或错误格式时停止，不切换账号或Plan',async()=>{const f=vi.fn();await expect(resetCodingPlan({...scope,credential:{...credential,bigmodel_access_token:undefined}},'status',{},f)).rejects.toThrow('授权');await expect(resetCodingPlan({...scope,assertCurrent(){throw Error('账号已变化')}},'status',{},f)).rejects.toThrow('账号已变化');expect(f).not.toHaveBeenCalled();await expect(resetCodingPlan(scope,'status',{},(async()=>response({...data,available_week_resets:[{expire_at:'tomorrow'}]})) as any)).rejects.toThrow('格式无效');})
})
